function Req($c,[string]$m){
 if(-not$c){
  if($m-like'science selftest *'){
   $detail=(Get-Variable -Name msg -Scope 1 -ErrorAction SilentlyContinue).Value
   if(-not[string]::IsNullOrWhiteSpace([string]$detail)){throw "WP5 validation failed: $m :: $detail"}
  }
  throw "WP5 validation failed: $m"
 }
}
function TestContainedPath([string]$baseFull,[string]$candidateFull){
 $relative=[IO.Path]::GetRelativePath($baseFull,$candidateFull);$nativeParent='..'+[IO.Path]::DirectorySeparatorChar;$alternateParent='..'+[IO.Path]::AltDirectorySeparatorChar
 -not[IO.Path]::IsPathRooted($relative)-and$relative-cne'..'-and-not$relative.StartsWith($nativeParent,[StringComparison]::Ordinal)-and-not$relative.StartsWith($alternateParent,[StringComparison]::Ordinal)
}
function GetCanonicalPath([string]$path,[string]$message){
 $full=[IO.Path]::GetFullPath($path);$pathRoot=[IO.Path]::GetPathRoot($full);$current=$pathRoot
 $relative=[IO.Path]::GetRelativePath($pathRoot,$full)
 if($relative-ceq'.'){return $full}
 foreach($segment in @($relative-split'[\\/]')){
  if([string]::IsNullOrWhiteSpace($segment)){continue}
  $next=[IO.Path]::GetFullPath([IO.Path]::Combine($current,$segment))
  if(Test-Path -LiteralPath $next){
   $item=Get-Item -Force -LiteralPath $next
   if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){
    try{$target=$item.ResolveLinkTarget($true)}catch{Req $false ($message+' canonical resolution')}
    Req($null-ne$target)($message+' canonical resolution')
    $current=[IO.Path]::GetFullPath($target.FullName)
   }else{$current=[IO.Path]::GetFullPath($item.FullName)}
  }else{$current=$next}
 }
 [IO.Path]::GetFullPath($current)
}
function GetContainedFullPath([string]$basePath,[string]$candidatePath,[string]$message){
 $baseFull=[IO.Path]::GetFullPath($basePath);$candidateFull=[IO.Path]::GetFullPath($candidatePath)
 Req(TestContainedPath $baseFull $candidateFull)$message
 $baseCanonical=GetCanonicalPath $baseFull $message;$candidateCanonical=GetCanonicalPath $candidateFull $message
 Req(TestContainedPath $baseCanonical $candidateCanonical)$message
 $candidateFull
}
function InvokeContainedPathFixture([string]$fixture){
 $fixtureParent=Join-Path $env:TEMP ('wp5-contained-path-fixture-'+[guid]::NewGuid().ToString('N'));$fixtureBase=Join-Path $fixtureParent 'root';$insideTarget=Join-Path $fixtureBase 'inside-target';$outsideTarget=Join-Path $fixtureParent 'escape';$prefixSibling=Join-Path $fixtureParent 'root-sibling'
 try{
  foreach($directory in @((Join-Path $fixtureBase 'child'),$insideTarget,$outsideTarget,$prefixSibling)){New-Item -ItemType Directory -Force -Path $directory|Out-Null}
  foreach($file in @((Join-Path $fixtureBase 'child/member.json'),(Join-Path $insideTarget 'member.json'),(Join-Path $outsideTarget 'member.json'),(Join-Path $prefixSibling 'member.json'))){[IO.File]::WriteAllText($file,'{}',[Text.UTF8Encoding]::new($false))}
  if($fixture-ceq'legal-child'){[void](GetContainedFullPath $fixtureBase (Join-Path $fixtureBase 'child/member.json') 'contained path legal child');return}
  $linkType=if(($PSVersionTable.PSEdition-ceq'Desktop')-or$IsWindows){'Junction'}else{'SymbolicLink'}
  if($fixture-ceq'internal-link'){$link=Join-Path $fixtureBase 'inside-link';New-Item -ItemType $linkType -Path $link -Target $insideTarget|Out-Null;[void](GetContainedFullPath $fixtureBase (Join-Path $link 'member.json') 'contained path internal link');return}
  if($fixture-ceq'prefix-sibling'){[void](GetContainedFullPath $fixtureBase (Join-Path $prefixSibling 'member.json') 'contained path prefix sibling');return}
  if($fixture-ceq'dotdot-escape'){[void](GetContainedFullPath $fixtureBase (Join-Path $fixtureBase '../escape/member.json') 'contained path dotdot escape');return}
  $link=Join-Path $fixtureBase 'escape-link';New-Item -ItemType $linkType -Path $link -Target $outsideTarget|Out-Null
  [void](GetContainedFullPath $fixtureBase (Join-Path $link 'member.json') 'contained path symlink escape')
 }finally{if(Test-Path -LiteralPath $fixtureParent){Remove-Item -Recurse -Force -LiteralPath $fixtureParent}}
}
