function GetSha256Text([string]$text){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($text))).ToLowerInvariant()}
function GetApprovedFrozenIntentHash([string]$path){
 Req(Test-Path -LiteralPath $path)'final reviews authorization spec'
 $normalized=(Get-Content -Raw -LiteralPath $path).Replace("`r`n","`n").Replace("`r","`n")
 $matches=[regex]::Matches($normalized,'(?s)<frozen-after-approval reason="human-owned intent — do not modify unless human renegotiates">.*?</frozen-after-approval>')
 Req($matches.Count-eq1)'final reviews authorization frozen block'
 GetSha256Text $matches[0].Value
}
function GetApprovedScopeAmendmentHash([string]$path){
