 $normalized=(Get-Content -Raw -LiteralPath $path).Replace("`r`n","`n").Replace("`r","`n")
 $matches=[regex]::Matches($normalized,'(?s)<approved-scope-amendment round="2" reason="user-authorized expansion after first review">.*?</approved-scope-amendment>')
 Req($matches.Count-eq1)'final reviews authorization scope amendment'
 GetSha256Text $matches[0].Value
}
