function AssertSelfTestStageContract{
 $expected=@('upstream-lineage','allowlist','registry','language-structure-boundary','publish','signoff','lineage-migration')
 $fixtureManifest=ReadStrictJson $selfTestFixtureManifestPath @('schema','fixtures') selftest_fixture_manifest;Req($fixtureManifest.schema-ceq'wp5-selftest-fixture-manifest-v3'-and@($fixtureManifest.fixtures).Count-eq300)'selftest fixture manifest identity';$fixtureIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($fixture in @($fixtureManifest.fixtures)){$oracle=@($fixture.expected_rejections);$validOracle=if([int]$fixture.expected_exit-eq0){$oracle.Count-eq0}elseif([int]$fixture.expected_exit-eq1){$oracle.Count-eq1-and-not[string]::IsNullOrWhiteSpace([string]$oracle[0])}else{$false};Req(-not(Compare-Object @($fixture.PSObject.Properties.Name) @('id','stage','canonical_case','expected_exit','expected_rejections'))-and$fixture.stage-in$expected-and$fixture.id-cmatch'^FXT-[A-Z0-9-]+-\d{3}$'-and$fixture.canonical_case-is[string]-and$fixture.canonical_case-ceq$fixture.id-and$fixtureIds.Add([string]$fixture.id)-and$validOracle)'selftest fixture manifest record'}
 Req($selfTestStages.Count-eq7-and-not(Compare-Object $selfTestStages $expected))'selftest stage exact set'
 Req(@($selfTestStageCases.Keys).Count-eq7-and-not(Compare-Object @($selfTestStageCases.Keys) $expected))'selftest case registry exact stage set'
 Req(@($selfTestStageCaseCounts.Keys).Count-eq7-and-not(Compare-Object @($selfTestStageCaseCounts.Keys) $expected))'selftest case count exact stage set'
 $count=0;foreach($stage in $expected){$ids=@($selfTestStageCases[$stage]);Req($ids.Count-gt0-and$ids.Count-eq@($ids|Sort-Object -Unique).Count)'selftest stage duplicate case '+$stage;Req([int]$selfTestStageCaseCounts[$stage]-ge$ids.Count)'selftest stage case count '+$stage;$count+=[int]$selfTestStageCaseCounts[$stage]};Req($count-eq300)'selftest exact fixture case total'
}
function InvokeSelfTestStageChild([string]$stage,[string[]]$childArgs){
 $exe=(Get-Process -Id $PID).Path;$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$exe;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 foreach($arg in @('-NoProfile','-File',$PSCommandPath)+$childArgs){[void]$psi.ArgumentList.Add($arg)}
 $proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi;Write-Host "SELFTEST_STAGE=$stage START";$null=$proc.Start();$stdoutTask=$proc.StandardOutput.ReadToEndAsync();$stderrTask=$proc.StandardError.ReadToEndAsync()
 $timeoutSeconds=([int]$selfTestStageCaseCounts[$stage]*180)+60;if(-not$proc.WaitForExit($timeoutSeconds*1000)){try{$proc.Kill($true)}finally{$proc.WaitForExit()};throw "WP5 selftest stage timeout stage=$stage timeout_seconds=$timeoutSeconds"}
 $output=$stdoutTask.GetAwaiter().GetResult()+$stderrTask.GetAwaiter().GetResult();Write-Host "SELFTEST_STAGE=$stage END exit=$($proc.ExitCode) timeout_seconds=$timeoutSeconds";[pscustomobject]@{exit_code=$proc.ExitCode;output=$output;timeout_seconds=$timeoutSeconds}
}
function StripMarkdownFences([string]$text){
 $out=[Collections.Generic.List[string]]::new();$inside=$false;$fenceChar='';$fenceLength=0
 foreach($line in [regex]::Split($text,'\r?\n')){
  if($inside){
   if($line-cmatch'^ {0,3}([`~]+)[ \t]*$'){$run=$Matches[1];$same=($run.ToCharArray()|?{$_-cne$fenceChar}).Count-eq0;if($same-and$run.Length-ge$fenceLength){$inside=$false}}
   continue
  }
  if($line-cmatch'^ {0,3}(`{3,}|~{3,})[^\r\n]*$'){$run=$Matches[1];$inside=$true;$fenceChar=[string]$run[0];$fenceLength=$run.Length;continue}
  $out.Add($line)
 }
 $out-join"`n"
}
function WalkJson($e,[string]$kind){if($e.ValueKind-ceq[Text.Json.JsonValueKind]::Object){$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($p in $e.EnumerateObject()){Req($seen.Add($p.Name))"duplicate $kind member";WalkJson $p.Value $kind}}elseif($e.ValueKind-ceq[Text.Json.JsonValueKind]::Array){foreach($x in $e.EnumerateArray()){WalkJson $x $kind}}}
function ExactJson($e,$names,[string]$kind){$actual=@($e.EnumerateObject()|%{$_.Name});Req($e.ValueKind-ceq[Text.Json.JsonValueKind]::Object-and$actual.Count-eq$names.Count-and@($names|?{-not($actual-ccontains$_)}).Count-eq0)"$kind exact schema"}
function ReadStrictJson($path,$names,[string]$kind){$text=gc -Raw -LiteralPath $path;try{$d=[Text.Json.JsonDocument]::Parse($text)}catch{Req $false "$kind json"};try{WalkJson $d.RootElement $kind;ExactJson $d.RootElement $names $kind}finally{$d.Dispose()};$text|ConvertFrom-Json}
function ValidateMarker([string]$text,[string]$id,$statuses,[string]$name){
 $ms=[regex]::Matches($text,'<!-- WP5-DOCUMENT id=([^ ]+) status=([^ ]+) evidence_id=([^ ]+) run_id=([^ ]+) manifest=([^ ]+) -->')
 Req($ms.Count-eq1)"document marker $name"
 $m=$ms[0];Req($m.Groups[1].Value-ceq$id)"document id $name";Req($statuses-ccontains$m.Groups[2].Value)"document status $name"
 Req($m.Groups[3].Value-ceq'EVD-WP5-GOVERNANCE'-and$m.Groups[4].Value-ceq'WP5-CONSISTENCY-v1'-and$m.Groups[5].Value-ceq'validation/wp5-consistency/active-output.json')"document evidence binding $name"
 Req(-not($text-cmatch'(?i)PPC.{0,30}(校准覆盖|coverage rate).{0,20}(通过|验收)'))"PPC coverage confusion $name"
 $promoted=@($text-split"`r?`n"|?{$_-notmatch'不得|不可执行|不代表|除非' -and $_-match'(?i)(pass|TODO).{0,120}(已实现|已测试|生产可用)'});Req($promoted.Count-eq0)"pseudocode promoted $name"
}
