function ValidateScience([string]$text,[string]$name){$prose=[regex]::Replace($text,'(?ms)^```.*?^```','');Req(-not($prose-cmatch'(?i)(Rhat|R-hat|R̂).{0,20}(<|≤).{0,5}(1\.05|1\.1)|ESS.{0,20}(>|≥).{0,5}(100|400)'))"duplicate diagnostic threshold $name";Req(-not($prose-cmatch'(?i)LOMO.{0,30}(贡献率为|贡献百分比为)'))"LOMO contribution $name";Req(-not($prose-cmatch'(?i)POD.{0,100}(采样效率提升|加速).{0,20}(数量级|倍)'))"POD acceleration $name";Req(-not($prose-cmatch'(?i)RJMCMC.{0,50}(已实现|生产可用|测试通过)'))"RJMCMC promoted $name";Req(-not($prose-cmatch'(?is)PPC.{0,80}(覆盖率通过|校准通过|Passed)'))"PPC calibration confusion $name";Req(-not($prose-cmatch'(?i)(直接输出|自动升级).{0,30}(可采资源量|正式资源量|储量)'))"formal resource promotion $name";Req(-not($prose-cmatch'(?i)(极限探测可达|可探测至|探测深度达).{0,15}(5000m|5km)'))"unconditional depth $name";Req(-not($prose-cmatch'(?i)(期权价值提升\s*\d+%|期望净现值\s*\d+\s*万元)'))"unbound economic number $name";Req(-not($prose-cmatch'(?i)(各方法)?贡献度合理'))"unsupported contribution grade $name";Req(-not($prose-cmatch'(?i)(收敛最快|不确定性降低\s*\d+\s*-\s*\d+%)'))"unbound performance claim $name";Req(-not($prose-cmatch'(?i)钻孔命中率\s*(>|≥)\s*\d+%'))"field hit-rate promotion $name"}
function ParsePythonContract($body){
 $im=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$sy=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$te=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
 foreach($x in $body){if($x-match'^\s*import\s+(.+?)(?:\s+#.*)?$'){foreach($part in $Matches[1]-split','){$module=(($part.Trim()-split'\s+as\s+')[0]).Trim();Req($module-cmatch'^[A-Za-z_][A-Za-z0-9_.]*$')'python import syntax';[void]$im.Add($module)}}elseif($x-match'^\s*from\s+([A-Za-z_][A-Za-z0-9_.]*)\s+import\s+(.+?)(?:\s+#.*)?$'){[void]$im.Add($Matches[1]);Req(-not[string]::IsNullOrWhiteSpace($Matches[2]))'python import syntax'};if($x-match'^\s*(?:async\s+)?(def|class)\s+([A-Za-z_][A-Za-z0-9_]*)'){$n=$Matches[2];[void]$sy.Add($n);if($n-cmatch'^(test_|Test)'){[void]$te.Add($n)}}}
 [pscustomobject]@{imports=@($im|Sort-Object);symbols=@($sy|Sort-Object);tests=@($te|Sort-Object)}
}
function AssertBalancedFlow([string]$value,[string]$kind){
 $stack=[Collections.Generic.Stack[char]]::new();$quote=[char]0;$escape=$false
 foreach($c in $value.ToCharArray()){if($quote-ne[char]0){if($quote-ceq'"'-and$escape){$escape=$false;continue};if($quote-ceq'"'-and$c-ceq'\'){$escape=$true;continue};if($c-ceq$quote){$quote=[char]0};continue};if($c-ceq'"'-or$c-ceq"'"){$quote=$c;continue};if($c-ceq'['-or$c-ceq'{'){$stack.Push($c);continue};if($c-ceq']'-or$c-ceq'}'){Req($stack.Count-gt0)"$kind structure";$open=$stack.Pop();Req(($open-ceq'['-and$c-ceq']')-or($open-ceq'{'-and$c-ceq'}'))"$kind structure"}}
 Req($quote-eq[char]0-and$stack.Count-eq0)"$kind structure"
}
function ParseYamlFlow([string]$value,[string]$path){
 $v=$value.Trim();AssertBalancedFlow $v 'yaml';$out=@()
 if($v.StartsWith('{')){Req($v.EndsWith('}'))'yaml structure';$inner=$v.Substring(1,$v.Length-2).Trim();$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);if($inner){foreach($part in SplitTomlItems $inner){Req(-not[string]::IsNullOrWhiteSpace($part)-and$part-cmatch'^([A-Za-z0-9_-]+)\s*:\s*(.+)$')'yaml structure';$k=$Matches[1];$child=$Matches[2];Req($seen.Add($k))'yaml duplicate key';$full=if($path){"$path.$k"}else{$k};$out+=$full;$out+=ParseYamlFlow $child $full}}}
 elseif($v.StartsWith('[')){Req($v.EndsWith(']'))'yaml structure';$inner=$v.Substring(1,$v.Length-2).Trim();if($inner){foreach($part in SplitTomlItems $inner){Req(-not[string]::IsNullOrWhiteSpace($part))'yaml structure';$out+=ParseYamlFlow $part ($path+'[]')}}}
 elseif($v.StartsWith('"')){Req($v-cmatch'^"(?:[^"\\]|\\.)*"$')'yaml structure'}
 elseif($v.StartsWith("'")){Req($v-cmatch"^'[^']*'$")'yaml structure'}
 else{Req($v-cnotmatch'^[\[\{]')'yaml structure'}
 @($out|Sort-Object -Unique)
}
function ParseYamlContract($body){
 $keys=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$seenAt=@{};$pathAt=@{};$seqAt=@{};$seqBaseAt=@{};$pending=$null;$blockIndent=-1;$previousIndent=0;$seen=0
 foreach($raw in $body){Req(-not$raw.Contains("`t"))'yaml indentation';$trim=$raw.Trim();if(-not$trim-or$trim.StartsWith('#')-or$trim-ceq'---'){continue};$indent=$raw.Length-$raw.TrimStart().Length
  if($blockIndent-ge0){if($indent-gt$blockIndent){$pending=$null;$seen++;continue};$blockIndent=-1}
  Req($indent%2-eq0-and$indent-le$previousIndent+2)'yaml indentation'
  if($null-ne$pending){Req($indent-gt$pending.indent-or($trim.StartsWith('- ') -and$indent-eq$pending.indent))'yaml block';$pending=$null}
  foreach($k in @($pathAt.Keys|?{[int]$_-gt$indent})){$pathAt.Remove($k)};foreach($k in @($seqBaseAt.Keys|?{[int]$_-gt$indent})){$seqBaseAt.Remove($k)}
  $isList=$trim.StartsWith('- ');$item=$trim;if($isList){$item=$trim.Substring(2).Trim();if(-not$seqBaseAt.ContainsKey($indent)){$seqBaseAt[$indent]=if($pathAt.ContainsKey($indent)){$pathAt[$indent]}elseif($indent-ge2-and$pathAt.ContainsKey($indent-2)){$pathAt[$indent-2]}else{''}};$parent=$seqBaseAt[$indent];$seqKey="$parent|$indent";if(-not$seqAt.ContainsKey($seqKey)){$seqAt[$seqKey]=0}else{$seqAt[$seqKey]++};$itemContext="$parent[]@$($seqAt[$seqKey])";$pathAt[$indent]=$itemContext;if(-not$item){$pending=[pscustomobject]@{indent=$indent};$previousIndent=$indent;$seen++;continue}}
  if($isList-and$item-cnotmatch'^[A-Za-z0-9_-]+\s*:'){Req(-not$item.StartsWith('{'))'yaml syntax';$parent=($pathAt[$indent]-replace'@\d+','');foreach($nested in ParseYamlFlow $item $parent){[void]$keys.Add($nested)};$previousIndent=$indent;$seen++;continue}
  Req($item-cmatch'^([A-Za-z0-9_-]+)\s*:\s*(.*)$')'yaml syntax';$key=$Matches[1];$value=$Matches[2];$parent=if($isList){$pathAt[$indent]}elseif($indent-ge2-and$pathAt.ContainsKey($indent-2)){$pathAt[$indent-2]}else{''};if(-not$isList){$seqBaseAt.Remove($indent)};$normParent=$parent-replace'@\d+','';$full=if($normParent){"$normParent.$key"}else{$key};$dupContext=if($parent-cmatch'\[\]@\d+$'){$parent}else{"$parent|$indent"};if(-not$seenAt.ContainsKey($dupContext)){$seenAt[$dupContext]=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)};Req($seenAt[$dupContext].Add($key))'yaml duplicate key';[void]$keys.Add($full)
  if($value-cmatch'^[|>][-+]?$'){$blockIndent=$indent;$pending=[pscustomobject]@{indent=$indent}}elseif(-not$value){$pathAt[$indent]=$full;$pending=[pscustomobject]@{indent=$indent}}else{foreach($nested in ParseYamlFlow $value $full){[void]$keys.Add($nested)}}
  $previousIndent=$indent;$seen++
