 Req($seen-gt0-and$null-eq$pending)'yaml block';@($keys|Sort-Object)
}
function SplitTomlItems([string]$value){
 $items=@();$start=0;$depth=0;$quote=[char]0;$escape=$false;$chars=$value.ToCharArray()
 for($i=0;$i-lt$chars.Count;$i++){$c=$chars[$i];if($quote-ne[char]0){if($quote-ceq'"'-and$escape){$escape=$false;continue};if($quote-ceq'"'-and$c-ceq'\'){$escape=$true;continue};if($c-ceq$quote){$quote=[char]0};continue};if($c-ceq'"'-or$c-ceq"'"){$quote=$c;continue};if($c-in@('[','{')){$depth++}elseif($c-in@(']','}')){$depth--}elseif($c-ceq','-and$depth-eq0){$items+=$value.Substring($start,$i-$start).Trim();$start=$i+1}}
 Req($quote-eq[char]0-and$depth-eq0)'toml value';$items+=$value.Substring($start).Trim();@($items)
}
function ValidateTomlValue([string]$value){
 $v=$value.Trim();Req(-not[string]::IsNullOrWhiteSpace($v))'toml value'
 if($v.StartsWith('"')){Req($v-cmatch'^"(?:[^"\\]|\\.)*"$')'toml string';return}
 if($v.StartsWith("'")){Req($v-cmatch"^'[^']*'$")'toml string';return}
 if($v.StartsWith('[')){Req($v.EndsWith(']'))'toml value';$inner=$v.Substring(1,$v.Length-2).Trim();if($inner){foreach($part in SplitTomlItems $inner){ValidateTomlValue $part}};return}
 if($v.StartsWith('{')){Req($v.EndsWith('}'))'toml value';$inner=$v.Substring(1,$v.Length-2).Trim();if($inner){$local=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($part in SplitTomlItems $inner){Req($part-cmatch'^([A-Za-z0-9_.-]+)\s*=\s*(.+)$')'toml value';Req($local.Add($Matches[1]))'toml duplicate key';ValidateTomlValue $Matches[2]}};return}
 if($v-cmatch'^\d{4}-\d{2}-\d{2}$'){$dt=[datetime]::MinValue;Req([datetime]::TryParseExact($v,'yyyy-MM-dd',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$dt))'toml value';return}
 if($v-cmatch'^\d{4}-\d{2}-\d{2}[Tt ]'){Req($v-cmatch'^\d{4}-\d{2}-\d{2}[Tt ]\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})?$')'toml value';$dto=[datetimeoffset]::MinValue;Req([datetimeoffset]::TryParseExact(($v-replace' ','T'),@('yyyy-MM-ddTHH:mm:ss','yyyy-MM-ddTHH:mm:ss.FFFFFFF','yyyy-MM-ddTHH:mm:ssK','yyyy-MM-ddTHH:mm:ss.FFFFFFFK'),[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$dto))'toml value';return}
 $digits=$v-replace'_','';Req($digits-cnotmatch'^[+-]?0\d' -and$v-cmatch'^(true|false|[+-]?\d(?:_?\d)*(?:\.\d(?:_?\d)*)?(?:[eE][+-]?\d+)?|[+-]?(?:inf|nan))$')'toml value'
}
function GetTomlInlineKeys([string]$value,[string]$path){
 $out=@();$v=$value.Trim();if(-not$v.StartsWith('{')){return @()};$inner=$v.Substring(1,$v.Length-2).Trim();if($inner){foreach($part in SplitTomlItems $inner){Req($part-cmatch'^([A-Za-z0-9_.-]+)\s*=\s*(.+)$')'toml value';$full="$path.$($Matches[1])";$out+=$full;$out+=GetTomlInlineKeys $Matches[2] $full}};@($out|Sort-Object -Unique)
}
function GetJsonKeys($element,[string]$path=''){
 $out=@();if($element.ValueKind-ceq[Text.Json.JsonValueKind]::Object){foreach($p in $element.EnumerateObject()){$full=if($path){"$path.$($p.Name)"}else{$p.Name};$out+=$full;$out+=GetJsonKeys $p.Value $full}}elseif($element.ValueKind-ceq[Text.Json.JsonValueKind]::Array){foreach($x in $element.EnumerateArray()){$out+=GetJsonKeys $x ($path+'[]')}};@($out|Sort-Object -Unique)
}
function ParseTomlContract($body){
 $keys=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$tables=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$table='';$pending='';$seen=0
 foreach($raw in $body){$quote=[char]0;$escape=$false;$cut=$raw.Length;for($ci=0;$ci-lt$raw.Length;$ci++){$cc=$raw[$ci];if($quote-ne[char]0){if($quote-ceq'"'-and$escape){$escape=$false;continue};if($quote-ceq'"'-and$cc-ceq'\'){$escape=$true;continue};if($cc-ceq$quote){$quote=[char]0};continue};if($cc-ceq'"'-or$cc-ceq"'"){$quote=$cc;continue};if($cc-ceq'#'){$cut=$ci;break}};$line=$raw.Substring(0,$cut).Trim();if(-not$line){continue};if($pending){$pending+="`n"+$line;try{AssertBalancedFlow $pending 'toml'}catch{continue};$line=$pending;$pending=''}
  if($line-cmatch'^\[\[([A-Za-z0-9_.-]+)\]\]$'){$table=$Matches[1];Req($tables.Add($table)-and-not($keys-ccontains$table)-and@($keys|?{$table.StartsWith($_+'.',[StringComparison]::Ordinal)-or$_.StartsWith($table+'.',[StringComparison]::Ordinal)}).Count-eq0)'toml duplicate table';$seen++;continue}
  if($line-cmatch'^\[([A-Za-z0-9_.-]+)\]$'){$table=$Matches[1];Req($tables.Add($table)-and-not($keys-ccontains$table)-and@($keys|?{$table.StartsWith($_+'.',[StringComparison]::Ordinal)}).Count-eq0)'toml duplicate table';$seen++;continue}
  Req($line-cmatch'(?s)^([A-Za-z0-9_.-]+)\s*=\s*(.+)$')'toml syntax';$key=$Matches[1];$value=$Matches[2];if($value.StartsWith('[')-or$value.StartsWith('{')){try{AssertBalancedFlow $value 'toml'}catch{$pending=$line;continue}};$full=if($table){"$table.$key"}else{$key};Req(-not($tables-ccontains$full)-and@($keys|?{$full.StartsWith($_+'.',[StringComparison]::Ordinal)-or$_.StartsWith($full+'.',[StringComparison]::Ordinal)}).Count-eq0-and$keys.Add($full))'toml duplicate key';ValidateTomlValue $value;foreach($nested in GetTomlInlineKeys $value $full){Req(@($keys|?{$_-cne$full-and($nested.StartsWith($_+'.',[StringComparison]::Ordinal)-or$_.StartsWith($nested+'.',[StringComparison]::Ordinal))}).Count-eq0-and$keys.Add($nested))'toml duplicate key'};$seen++
 }
 Req($seen-gt0-and-not$pending)'toml structure';@($keys|Sort-Object)
}
function DeriveClaimType([string]$line){
 if($line-cmatch'(?i)RJMCMC|Green move|Jacobian|forward density|reverse density'){return 'rjmcmc'}
 if($line-cmatch'(?i)POD|proper orthogonal'){return 'pod'}
 if($line-cmatch'(?i)LOMO|消融KL'){return 'lomo'}
 if($line-cmatch'(?i)实现信息增益|realized information gain|先验.{0,20}后验.{0,20}KL'){return 'realized_ig'}
 if($line-cmatch'(?i)EIG|期望信息增益|设计信息增益'){return 'design_eig'}
 if($line-cmatch'(?i)资源量|储量|P10|P50|P90|吨位|金属量'){return 'resource'}
 if($line-cmatch'(?i)DOI|有效深度|探测深度|目标深度|埋深|深度范围|深度能力|点距|测线间距'){return 'depth'}
 if($line-cmatch'(?i)PPC|SBC|校准|coverage|PIT|rank statistic'){return 'calibration'}
 if(($line-cmatch'(?i)Rhat|R-hat|R̂')-and($line-cmatch'(?i)ESS')-and($line-cmatch'(?i)MCSE')){return 'diagnostic'}
 'quantitative'
}
function DeriveLanguageClaimType([string]$line){
 $negative=$line-cmatch'不得|不能|不保证|不包含|不输出|不报告|不声称|不构成|不据|未绑定|没有相应|尚无|撤销|仅输出|已完成(任务|详查|勘探)|保持Planned|保持 Pending|接口草案|候选'
 if($line-cmatch'(?i)国际领先|超越.{0,20}(软件|体系)|完整(系统|产业链)|已实现|已完成|生产可用|合成.{0,12}通过|原型.{0,12}完成'){if(-not$negative){return 'achievement'}}
 if($line-cmatch'(?i)(采购|人工|能耗).{0,20}(成本|费用|投入)|(成本|费用|投入).{0,20}(采购|人工|能耗)|收益|回收期|ROI|NPV|IRR|投资评级|经济效益'){if(-not$negative){return 'economic'}}
 if($line-cmatch'(?i)大幅降低|显著提升|高性能|保证.{0,12}(精度|收敛)|加速成果|性能优异'){if(-not$negative){return 'performance'}}
 if($line-cmatch'(?i)直接.{0,20}(钻孔|钻探)|立即钻探|自动升级|阶段升级.{0,10}(标准|判定)|通用通过线'){if(-not$negative){return 'action'}}
 return ''
}
