 $fields=@('id','kind','document','span_start','span_end','text_sha256','claim_type','metric','formula_id','status','scope','source','evidence_id','run_id','manifest');$seenId=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$seenSpan=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$types=@('quantitative','diagnostic','depth','calibration','resource','pod','interface-draft','design_eig','realized_ig','lomo','rjmcmc','achievement','economic','performance','action')
