function AssertTombstoneContinuity($old,$new,[string]$label){$oldActive=@($old.entries);$oldTomb=@($old.tombstones);$newActive=@($new.entries);$newTomb=@($new.tombstones);$oldTombIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($t in $oldTomb){[void]$oldTombIds.Add([string]$t.id)};$newTombIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($t in $newTomb){Req(-not(Compare-Object @($t.PSObject.Properties.Name) @('id','old_text_sha256','document','span_start','span_end')))'ledger tombstone exact';$uniqueFailure=if($label-ceq'loop30'){'ledger tombstone id'}else{"$label tombstone unique"};Req($newTombIds.Add([string]$t.id)-and@($newActive|?{ $_.id -ceq $t.id }).Count-eq0)$uniqueFailure;$prior=@($oldActive|?{ $_.id -ceq $t.id })+@($oldTomb|?{ $_.id -ceq $t.id });Req($prior.Count-eq1)"$label tombstone predecessor";if($prior[0].PSObject.Properties['text_sha256']){Req($prior[0].text_sha256-ceq$t.old_text_sha256-and$prior[0].document-ceq$t.document-and$prior[0].span_start-eq$t.span_start-and$prior[0].span_end-eq$t.span_end)"$label tombstone binding"}else{Req($prior[0].old_text_sha256-ceq$t.old_text_sha256-and$prior[0].document-ceq$t.document-and$prior[0].span_start-eq$t.span_start-and$prior[0].span_end-eq$t.span_end)"$label tombstone carry"}};$removed=@($oldActive|?{$_.id-notin@($newActive.id)});$added=@($newTomb|?{$_.id-notin@($oldTomb.id)});Req($removed.Count-eq$added.Count-and-not(Compare-Object @($removed.id|Sort-Object) @($added.id|Sort-Object)))"$label tombstone delta"}
