function AssertMigration($name,$old,$new){$meta=$lineage.migrations.$name;$mp=Join-Path $vroot $meta.path;Req((Get-FileHash -Algorithm SHA256 $mp).Hash.ToLowerInvariant()-ceq$meta.sha256)"ledger migration hash $name";$keys=if($name-ceq'loop28'){@('schema','source_ledger_sha256','replacements','tombstones','document_remediations','entries')}else{@('schema','source_ledger_sha256','replacements','tombstones','entries')};$migration=ReadStrictJson $mp $keys "ledger_migration_$name";$oldHash=(Get-FileHash -Algorithm SHA256 (Join-Path $vroot $lineage.anchors.($meta.from).path)).Hash.ToLowerInvariant();Req($migration.schema-ceq'wp5-ledger-text-migration-v1'-and$migration.source_ledger_sha256-ceq$oldHash-and[int]$migration.replacements-eq[int]$meta.replacements-and[int]$migration.tombstones-eq[int]$meta.tombstones-and@($migration.entries).Count-eq([int]$meta.replacements+[int]$meta.tombstones))"ledger migration identity $name";$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($entry in @($migration.entries)){$want=if($entry.disposition-ceq'replacement'){@('id','disposition','old','new_entry','reason')}else{@('id','disposition','old','reason')};Req(-not(Compare-Object @($entry.PSObject.Properties.Name) $want)-and$entry.disposition-in@('replacement','tombstone')-and$seen.Add([string]$entry.id)-and-not[string]::IsNullOrWhiteSpace([string]$entry.reason))"ledger migration exact $name";Req(-not(Compare-Object @($entry.old.PSObject.Properties.Name) @('id','old_text_sha256','document','span_start','span_end')))'ledger migration old exact';$prior=@($old.entries|?{ $_.id -ceq $entry.id });Req($prior.Count-eq1-and$prior[0].text_sha256-ceq$entry.old.old_text_sha256-and$prior[0].document-ceq$entry.old.document-and$prior[0].span_start-eq$entry.old.span_start-and$prior[0].span_end-eq$entry.old.span_end)"ledger migration old binding $name";if($entry.disposition-ceq'replacement'){$current=@($new.entries|?{ $_.id -ceq $entry.id });Req($current.Count-eq1-and-n