function AssertFixtureResultOracle($result,$oracle,[string]$prefix){
 Req(-not(Compare-Object @($result.PSObject.Properties.Name) @('fixture_id','case','expected_exit','actual_exit','expected_rejections','actual_rejection','success_criterion','matched','duration_ms'))-and[bool]$result.matched-and[int64]$result.duration_ms-ge0)($prefix+' fixture result')
 $eventExpected=@($result.expected_rejections);$oracleExpected=@($oracle.expected_rejections)
 Req($result.fixture_id-ceq$oracle.id-and$result.case-is[string]-and$result.case-ceq$oracle.canonical_case-and[int]$result.expected_exit-eq[int]$oracle.expected_exit-and$eventExpected.Count-eq$oracleExpected.Count-and($eventExpected-join"`0")-ceq($oracleExpected-join"`0"))($prefix+' fixture oracle')
 $expectedCriterion=if([int]$oracle.expected_exit-eq0){'child accepts this positive fixture'}else{'child rejects this fixture with one predeclared business assertion'}
 $validOutcome=if([int]$oracle.expected_exit-eq0){[int]$result.actual_exit-eq0-and[string]::IsNullOrEmpty([string]$result.actual_rejection)}else{[int]$result.actual_exit-ne0-and$oracleExpected.Count-eq1-and[string]$result.actual_rejection-ceq[string]$oracleExpected[0]}
 Req($validOutcome-and$result.success_criterion-ceq$expectedCriterion)($prefix+' fixture outcome')
}
