  foreach($arg in @('-NoProfile','-File',$file)+$childArgs){[void]$psi.ArgumentList.Add($arg)}
  $proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi;Write-Host "SELFTEST_STAGE=$stage START";$null=$proc.Start();$stdoutTask=$proc.StandardOutput.ReadToEndAsync();$stderrTask=$proc.StandardError.ReadToEndAsync()
  if(-not$proc.WaitForExit(180000)){try{$proc.Kill($true)}finally{$proc.WaitForExit()};throw "WP5 selftest child timeout stage=$stage timeout_seconds=180"}
  $out=$stdoutTask.GetAwaiter().GetResult()+$stderrTask.GetAwaiter().GetResult();Write-Host "SELFTEST_STAGE=$stage END exit=$($proc.ExitCode)"
  [pscustomobject]@{exit_code=$proc.ExitCode;output=$out}
 }
 function TestLoop29RegistrySelfTest{
  $iso=Join-Path $env:TEMP ('wp5-registry-stage-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $iso|Out-Null
