   Get-ChildItem -LiteralPath $root -Force|%{Copy-Item -Recurse -Force -LiteralPath $_.FullName -Destination $iso}
  foreach($case in @('scope_delete','scope_source','scope_owner','risk_delete','risk_replace')){
   try{
    $iv=Join-Path $iso 'validation/wp5-consistency'
    Copy-Item -Force -LiteralPath (Join-Path $vroot 'scope-registry.json') -Destination (Join-Path $iv 'scope-registry.json');Copy-Item -Force -LiteralPath (Join-Path $vroot 'high-risk-classification.json') -Destination (Join-Path $iv 'high-risk-classification.json')
    if($case-like'scope_*'){$f=Join-Path $iv 'scope-registry.json';$z=gc -Raw $f|ConvertFrom-Json;$p=@($z.scopes.PSObject.Properties)[0];if($case-ceq'scope_delete'){$z.scopes.PSObject.Properties.Remove($p.Name)}elseif($case-ceq'scope_source'){$p.Value.source='WRONG.md#L1'}else{$p.Value.owner='WRONG'};$z|ConvertTo-Json -Depth 12|Set-Content -Encoding utf8 $f;$expect='scope registry frozen constants'}else{$f=Join-Path $iv 'high-risk-classification.json';$z=gc -Raw $f|ConvertFrom-Json;if($case-ceq'risk_delete'){$z.rules=@($z.rules|select -Skip 1)}else{$z.rules[0].pattern='replacement-pattern'};$z|ConvertTo-Json -Depth 12|Set-Content -Encoding utf8 $f;$expect='risk frozen constants'}
    $result=InvokeSelfTestChild "loop29-registry/$case" (Join-Path $iso 'validate-wp5.ps1') @('-SemanticOnly');$msg=$result.output
    $accepted=if($case-ceq'scope_delete'){@('scope registry frozen constants','scope registry use exact')}elseif($case-ceq'scope_source'){@('scope registry frozen constants','scope registry source')}elseif($case-ceq'scope_owner'){@('scope registry frozen constants','scope registry owner')}else{@($expect)}
    $passed=@($accepted|?{$msg.Contains('WP5 validation failed: '+$_)}).Count-gt0;Req($result.exit_code-ne0-and$passed)"registry selftest $case :: $msg"
   }catch{throw} 
  }
  }finally{Remove-Item -Recurse -Force $iso}
 }
 if($SelfTestStage-ceq'loop29-registry'){TestLoop29RegistrySelfTest;"PASS self_test_stage=$SelfTestStage";return}
