  $iso=Join-Path $env:TEMP ('wp5-science-'+[guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory $iso|Out-Null
  try{
   CopySemanticFixture $iso
   $fixtureArgs=@()
   if($q.Key-in@('pod','rjmcmc')){
    $f03=Join-Path $iso '03-多方法深度融合的核心技术实现路径.md'
    $t=gc -Raw -LiteralPath $f03
    if($q.Key-ceq'pod'){
     $old='薄SVD下不能删除正交补项'
     $new='薄SVD下可以删除正交补项'
     $recordId='CLM-DOC-03-0005'
    }else{
     $old='\pi(y)\,j_{\ell^\star}(y)\,q_{\ell^\star}(u''\mid y)'
     $new='\pi(y)'
     $recordId='CLM-DOC-03-0007'
    }
    Req(([regex]::Matches($t,[regex]::Escape($old))).Count-eq1)"$($q.Key) scientific fixture source"
    $t=$t.Replace($old,$new)
    $t|Set-Content -Encoding utf8 -LiteralPath $f03
    $lf=Join-Path $iso 'validation/wp5-consistency/claim-ledger.json'
    $lz=gc -Raw -LiteralPath $lf|ConvertFrom-Json
    $lr=@($lz.entries|?{$_.id-ceq$recordId})
    Req($lr.Count-eq1)"$($q.Key) scientific fixture ledger"
    $dl=@(gc -LiteralPath $f03)
    $span=($dl[([int]$lr[0].span_start-1)..([int]$lr[0].span_end-1)]-join"`n").Trim()-replace'\s+',' '
    $lr[0].text_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($span))).ToLowerInvariant()
    $lz|ConvertTo-Json -Depth 24|Set-Content -Encoding utf8 -LiteralPath $lf
    $fixtureArgs+='-FixtureMutation'
   }else{
    Add-Content -Encoding utf8 (Join-Path $iso '00-摘要.md') $q.Value[0]
   }
   $msg=(&$exe -NoProfile -File (Join-Path $iso 'validate-wp5.ps1') -SemanticOnly @fixtureArgs 2>&1|Out-String)
   Req($LASTEXITCODE-ne0-and$msg.Contains('WP5 validation failed: '+$q.Value[1]))"science selftest $($q.Key)"
  }finally{
   Remove-Item -Recurse -Force $iso
   Remove-Variable selfTestCaseLabel -ErrorAction SilentlyContinue
  }
 }
