if($SkipSignoff){"PASS run_id=$($ptr.run_instance_id) skip_signoff=True authorization_verified=True release_evidence_verified=True";exit 0}
$scopeSignoff=gc -Raw (Join-Path $root 'WP5-主编技术编辑与专项交叉复核独立签核.md')
Req([regex]::Matches($scopeSignoff,'(?m)^'+[regex]::Escape($scopeLine)+'\s*$').Count-eq1-and[regex]::Matches($scopeSignoff,'(?m)^'+[regex]::Escape($excludeLine)+'\s*$').Count-eq1)'signoff exact 16+1 scope'
$reviewState=ValidateFinalRootReviews $roots $ptr $authorizationSpecPath $releaseState $implementationRoot
$sg=StripMarkdownFences (gc -Raw (Join-Path $root 'WP5-主编技术编辑与专项交叉复核独立签核.md'))
$bindings=@([regex]::Matches($sg,'(?m)^- 输入版本：`'+[regex]::Escape($ptr.run_instance_id)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- manifest SHA-256：`'+[regex]::Escape($ptr.manifest_sha256)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- 成员清单内容根SHA-256：`'+[regex]::Escape($roots.member)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- 根清单文件SHA-256：`'+[regex]::Escape($roots.file)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- 授权冻结块SHA-256：`'+[regex]::Escape($reviewState.authorization_hash)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- Round-2授权修正块SHA-256：`'+[regex]::Escape($reviewState.amendment_hash)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- CI workflow SHA-256：`'+[regex]::Escape($reviewState.ci_workflow_hash)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- release evidence envelope SHA-256：`'+[regex]::Escape($releaseState.sha256)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- 六角色reviews manifest SHA-256：`'+[regex]::Escape($reviewState.manifest_sha256)+'`\s*$').Count,[regex]::Matches($sg,'(?m)^- 身份类型：`automated-ai-final-root-review`\s*$').Count)
Req(@($bindings|?{$_-ne1}).Count-eq0)'signoff root binding'
$roles=@('主编','技术编辑','地球物理复核','贝叶斯/UQ复核','算法数值复核','工程架构复核')
$statusLines=[regex]::Matches($sg,'(?m)^- (状态|主编|技术编辑|地球物理复核|贝叶斯/UQ复核|算法数值复核|工程架构复核|[^：\r\n]+)：(PASS|Pending|FAIL)\s*$')
$ok=$statusLines.Count-eq7-and[regex]::Matches($sg,'(?m)^- 状态：PASS\s*$').Count-eq1
foreach($role in $roles){$ok=$ok-and[regex]::Matches($sg,'(?m)^- '+[regex]::Escape($role)+'：PASS\s*$').Count-eq1}
Req($ok)'independent signoff Pending'
"PASS run_id=$($ptr.run_instance_id) self_test=$([bool]$SelfTest)"
exit 0
